import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("successful sign-in returns a session", { tag: "@AUTH-01" }, async ({ request }) => {
  // Act
  const response = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD },
  });

  // Assert
  expect(response.status(), await response.text()).toBe(200);
  const body = (await response.json()) as { access_token?: string };
  expect(body.access_token, await response.text()).toBeTruthy();

  const cookies = response.headersArray().filter((h) => h.name.toLowerCase() === "set-cookie");
  const session = cookies.find((h) => h.value.startsWith("session="));
  expect(session, "session cookie should be set").toBeDefined();
  expect(session?.value.toLowerCase(), "session cookie should be HttpOnly").toContain("httponly");
});
